        vbrp_ship.J_3GPMAUFE AS VBRP_SHIP_PM_ORDER_NUMBER_J_3GPMAUFE,
        vbrp_ship.J_3GPMAUFV AS VBRP_SHIP_PM_ORDER_NUMBER_J_3GPMAUFV,
        vbrp_ship.J_3GETYPA AS VBRP_SHIP_SENDING_RECIPIENT_TYPE,
        vbrp_ship.J_3GETYPE AS VBRP_SHIP_RECEIVING_RECIPIENT_TYPE,
        vbrp_ship.J_3GORGUEB AS VBRP_SHIP_INDICATOR_ACROSS_ALL_ORGANIZATIONAL_STRUCTURES,
        vbrp_ship.PRS_WORK_PERIOD AS VBRP_SHIP_WORK_PERIOD,
        vbrp_ship.PPRCTR AS VBRP_SHIP_PARTNER_PROFIT_CENTER,
        vbrp_ship.PARGB AS VBRP_SHIP_TRADING_PARTNER_S_BUSINESS_AREA,
        vbrp_ship.AUFPLOAA AS VBRP_SHIP_ROUTING_NUMBER_OF_OPERATIONS_IN_THE_ORDER_AUFPLOAA,
        vbrp_ship.APLZLOAA AS VBRP_SHIP_INTERNAL_COUNTER_APLZLOAA,
        vbrp_ship.CAMPAIGN AS VBRP_SHIP_GENERIC_PROJECT_PLANNING_GUID_FROM_EXTERNAL_R_3_SYSTEM,
        vbrp_ship.COMPREAS AS VBRP_SHIP_ABBREVIATION_FOR_COMPLAINTS_REASON,
        vbrp_ship.WRF_CHARSTC1 AS VBRP_SHIP_CHARACTERISTIC_VALUE_1,
        vbrp_ship.WRF_CHARSTC2 AS VBRP_SHIP_CHARACTERISTIC_VALUE_2,
        vbrp_ship.WRF_CHARSTC3 AS VBRP_SHIP_CHARACTERISTIC_VALUE_3
    FROM {{ ref('ODS__SAPAPI__ZCDV_T_CMTU027_EKKO') }} ekko
            LEFT JOIN {{ ref('ODS__SAPAPI__ZCDV_T_CMTU028_EKPO') }} ekpo
	            ON ekpo.EBELN = ekko.EBELN
            LEFT JOIN lips_cte lips  -- Delivery Line
                ON lips.VGBEL = ekpo.EBELN AND lips.VGPOS = ekpo.EBELP
            LEFT JOIN likp_cte likp -- Delivery Head
                ON likp.VBELN = lips.VBELN
            LEFT JOIN (SELECT * FROM {{ ref('ODS__SAPAPI__ZCDV_T_CMTU015_VBRP') }} where  VGTYP = 'C')  vbrp_bill -- Billing Document Item
                ON vbrp_bill.VGBEL = ekpo.EBELN AND vbrp_bill.VGPOS = ekpo.EBELP
            LEFT JOIN {{ ref('ODS__SAPAPI__ZCDV_T_CMTU014_VBRK') }} vbrk_bill -- Billing Document Head
                ON vbrk_bill.VBELN = vbrp_bill.VBELN
            LEFT JOIN (SELECT * FROM {{ ref('ODS__SAPAPI__ZCDV_T_CMTU015_VBRP') }} where  VGTYP = 'J') vbrp_ship -- Billing Document Item
                ON vbrp_ship.VGBEL = LIPS.VGBEL AND vbrp_ship.VGPOS = LIPS.VGPOS
            LEFT JOIN {{ ref('ODS__SAPAPI__ZCDV_T_CMTU014_VBRK') }} vbrk_ship -- Billing Document Head
                ON vbrk_ship.VBELN = vbrp_ship.VBELN
),

