type_data as
(
    SELECT
        CAST(EKKO_PURCHASING_DOCUMENT_NUMBER as VARCHAR(16777216)) AS EKKO_PURCHASING_DOCUMENT_NUMBER,
        CAST(EKKO_COMPANY_CODE as VARCHAR(16777216)) AS EKKO_COMPANY_CODE,
        CAST(EKKO_PURCHASING_DOCUMENT_CATEGORY as VARCHAR(16777216)) AS EKKO_PURCHASING_DOCUMENT_CATEGORY,
