        CAST(DELIVERY_CREATE_DATE as VARCHAR(16777216)) AS DELIVERY_CREATE_DATE,
        CAST(DELIVERY_CERATOR as VARCHAR(16777216)) AS DELIVERY_CERATOR,
        CAST(CHANGE_TIME_STAMP as VARCHAR(16777216)) AS CHANGE_TIME_STAMP,
        CAST(ITEM_NUMBER_INTERVAL as VARCHAR(16777216)) AS ITEM_NUMBER_INTERVAL,
        CAST(LAST_ITEM_NUMBER as VARCHAR(16777216)) AS LAST_ITEM_NUMBER,
        CAST(VENDOR_S_ACCOUNT_NUMBER as VARCHAR(16777216)) AS VENDOR_S_ACCOUNT_NUMBER,
        CAST(LANGUAGE_KEY as VARCHAR(16777216)) AS LANGUAGE_KEY,
        CAST(TERMS_OF_PAYMENT_KEY as VARCHAR(16777216)) AS TERMS_OF_PAYMENT_KEY,
        CAST(CASH_DISCOUNT_DAYS_ZBD1T as VARCHAR(16777216)) AS CASH_DISCOUNT_DAYS_ZBD1T,
        CAST(CASH_DISCOUNT_DAYS_ZBD2T as VARCHAR(16777216)) AS CASH_DISCOUNT_DAYS_ZBD2T,
        CAST(CASH_DISCOUNT_DAYS_ZBD3T as VARCHAR(16777216)) AS CASH_DISCOUNT_DAYS_ZBD3T,
        CAST(CASH_DISCOUNT_PERCENTAGE_1 as VARCHAR(16777216)) AS CASH_DISCOUNT_PERCENTAGE_1,
        CAST(CASH_DISCOUNT_PERCENTAGE_2 as VARCHAR(16777216)) AS CASH_DISCOUNT_PERCENTAGE_2,
        CAST(PURCHASING_ORGANIZATION_EKORG as VARCHAR(16777216)) AS PURCHASING_ORGANIZATION_EKORG,
