        CAST(EXCHANGE_RATE as VARCHAR(16777216)) AS EXCHANGE_RATE,
        CAST(INDICATOR_FOR_FIXED_EXCHANGE_RATE as VARCHAR(16777216)) AS INDICATOR_FOR_FIXED_EXCHANGE_RATE,
        CAST(PURCHASING_DOCUMENT_DATE as VARCHAR(16777216)) AS PURCHASING_DOCUMENT_DATE,
        CAST(START_OF_VALIDITY_PERIOD as VARCHAR(16777216)) AS START_OF_VALIDITY_PERIOD,
        CAST(END_OF_VALIDITY_PERIOD as VARCHAR(16777216)) AS END_OF_VALIDITY_PERIOD,
        CAST(CLOSING_DATE_FOR_APPLICATIONS as VARCHAR(16777216)) AS CLOSING_DATE_FOR_APPLICATIONS,
